def is_square(n):
    if n < 0:
        return False
    r = int(math.isqrt(n))
    return r*r == n

def square_factor(n):
    # returns t such that t^2 | n and n/(t^2) is squarefree
    t = 1
    temp = n
    # factor 2
    cnt = 0
    while temp % 2 == 0:
        temp //= 2
        cnt += 1
    if cnt >= 2:
        t *= 2**(cnt//2)
    p = 3
    while p*p <= temp:
        cnt = 0
        while temp % p == 0:
            temp //= p
            cnt += 1
        if cnt >= 2:
            t *= p**(cnt//2)
        p += 2
    # any remaining temp is prime (count 1), contributes nothing to t
    return t

